def drop_mapping_from_steps(apps, schema_editor):
    """Steps no longer copy answers onto the proposal: drop field_map and
    resources from flows saved before, so they validate as they are now."""
    FormFlow = apps.get_model("proposal_forms", "FormFlow")
    for flow in FormFlow.objects.all():
        steps = [
            {key: step[key] for key in KEPT_STEP_KEYS if key in step}
            for step in flow.steps
        ]
        if steps != flow.steps:
            flow.steps = steps
            flow.save(update_fields=["steps"])


